// Экран почтовых копий и оформление возвратов.
let _mailConfig=null,_mailLoading=false,_returnDraft=null;
async function renderMailSettings(){
  const card=document.getElementById('mailSettingsCard'),body=document.getElementById('mailSettingsBody');
  if(!card||window.AUTH.perms!=='*')return;card.style.display='block';
  if(body.dataset.ready||_mailLoading)return;_mailLoading=true;
  try{_mailConfig=await window.DB.mail.get();const d=_mailConfig;
    body.innerHTML='<p class="bk-t">Копия отправляется сервером каждый день, даже когда CRM закрыта. Ручная выгрузка остаётся в разделе «Безопасность».</p>'+
      '<label class="lbl" for="mailEnabled"><input id="mailEnabled" type="checkbox" style="width:44px;height:44px;vertical-align:middle" '+(d.enabled?'checked':'')+'> Отправлять каждый день</label>'+
      '<label class="lbl" for="mailEmail">Получатель</label><input class="inp" id="mailEmail" type="email" autocomplete="email" value="'+esc(d.email)+'"/>'+
      '<label class="lbl" for="mailTime">Время по Москве</label><input class="inp" id="mailTime" type="time" value="'+esc(d.time)+'"/>'+
      '<label class="lbl" for="mailPassword">Пароль копий</label><input class="inp" id="mailPassword" type="password" autocomplete="new-password" placeholder="'+(d.hasPassword?'Уже задан. Введите новый для смены':'Не меньше 8 символов')+'"/>'+
      '<p class="bk-t">Пароль не отправляется в письме. Сохраните его отдельно: без него копию открыть нельзя.</p>'+
      (!d.smtpReady?'<p class="bk-err">Отправка писем ещё не подключена. Администратору нужно настроить почтовую службу на сервере.</p>':'')+
      '<div class="bk-row"><button class="btn bg" id="mailSave" onclick="saveMailSettings()">Сохранить</button><button class="btn bgh" id="mailSend" onclick="sendMailBackup()">Отправить сейчас</button></div><div id="mailResult" role="status"></div><div id="mailLast"></div>';
    body.dataset.ready='1';showMailStatus(d);
  }catch(e){body.textContent='Не удалось загрузить настройки: '+e.message;}finally{_mailLoading=false;}
}
function showMailStatus(d){const el=document.getElementById('mailLast');if(el)el.innerHTML='<p class="bk-t">Последняя отправка: '+(d.lastSent?esc(new Date(d.lastSent).toLocaleString('ru-RU',{timeZone:'Europe/Moscow'})):'ещё не было')+'</p>'+(d.lastError?'<p class="bk-err">'+esc(d.lastError)+'</p>':'');}
async function saveMailSettings(){const b=document.getElementById('mailSave'),r=document.getElementById('mailResult');if(b.disabled)return;b.disabled=true;r.textContent='Сохраняю…';try{_mailConfig=await window.DB.mail.save({enabled:document.getElementById('mailEnabled').checked,email:document.getElementById('mailEmail').value.trim(),time:document.getElementById('mailTime').value,password:document.getElementById('mailPassword').value});document.getElementById('mailPassword').value='';document.getElementById('mailPassword').placeholder='Пароль уже задан';r.textContent='Настройки сохранены';showMailStatus(_mailConfig);}catch(e){r.textContent=e.message;}finally{b.disabled=false;}}
async function sendMailBackup(){const b=document.getElementById('mailSend'),r=document.getElementById('mailResult');if(b.disabled)return;b.disabled=true;r.textContent='Готовлю и отправляю зашифрованную копию…';try{_mailConfig=await window.DB.mail.send();r.textContent='Письмо отправлено на сохранённый адрес. Проверьте почту и папку «Спам».';showMailStatus(_mailConfig);}catch(e){r.textContent=e.message;}finally{b.disabled=false;}}
function returnRemaining(c){const discounts=S.payments.filter(p=>p.clientId===c.id&&p.type==='discount').reduce((n,p)=>n+(parseFloat(p.amount)||0),0);return R2(c.price-(c.returnedAmount||0)-discounts);}
function openReturn(id){
  if(!can('deal_edit')||!can('pay_cancel')){toast('Нет права на возврат','ter');return;}
  const c=S.clients.find(c=>c.id===id);if(!c)return;const max=returnRemaining(c);if(max<=0){toast('Договор уже полностью возвращён','ter');return;}
  document.getElementById('mReturn')?.remove();_returnDraft={id,requestId:Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('')};
  const el=document.createElement('div');el.id='mReturn';el.className='mover on';el.innerHTML='<div class="modal" role="dialog" aria-modal="true" aria-labelledby="returnTitle"><div class="m-head"><div class="mtitle" id="returnTitle">Возврат товара / денег</div><button class="ib m-x" aria-label="Закрыть" onclick="closeReturn()">×</button></div><p>'+esc(c.name)+' · №'+esc(c.contractId)+'</p><label class="lbl" for="returnAmount">Стоимость возвращаемой части после скидок</label><input class="inp" id="returnAmount" type="text" inputmode="decimal" value="'+fmt(max)+'" oninput="returnHint()"/><p class="bk-t">Не больше '+fmt(max)+' ₽. Долг уменьшится; излишне полученные деньги будут возвращены клиенту.</p><label class="lbl" for="returnWallet">Откуда вернуть деньги</label><select class="inp sel" id="returnWallet">'+S.wallets.map(w=>'<option value="'+w.id+'">'+esc(w.name)+'</option>').join('')+'</select><label class="lbl" for="returnReason">Причина возврата</label><textarea class="inp" id="returnReason" maxlength="2000"></textarea><p id="returnHint" role="status"></p><p class="bk-t">Возврат записывается сегодняшней датой. Исходные оплаты и закрытые месяцы сохраняются в истории.</p><div class="mft"><button class="btn bgh" onclick="closeReturn()">Отмена</button><button class="btn bg" id="returnSave" onclick="saveReturn()">Оформить возврат</button></div></div>';
  document.body.appendChild(el);returnHint();
}
function closeReturn(){document.getElementById('mReturn')?.remove();_returnDraft=null;}
function returnHint(){const c=_returnDraft&&S.clients.find(c=>c.id===_returnDraft.id);if(!c)return;const a=parseNum(document.getElementById('returnAmount').value),refund=R2(Math.max(0,a-getStats(c).balance));document.getElementById('returnHint').textContent='К возврату деньгами: '+fmt(refund)+' ₽. Остаток долга: '+fmt(Math.max(0,getStats(c).balance-a))+' ₽.';}
async function saveReturn(){const draft=_returnDraft,b=document.getElementById('returnSave');if(!draft||b.disabled)return;b.disabled=true;try{const result=await window.DB.returnDeal({clientId:draft.id,requestId:draft.requestId,amount:parseNum(document.getElementById('returnAmount').value),wallet:document.getElementById('returnWallet').value,reason:document.getElementById('returnReason').value.trim()});closeReturn();toast('Возврат оформлен. Клиенту возвращено '+fmt(result.refundAmount)+' ₽','tok');}catch(e){toast(e.message,'ter');b.disabled=false;}}
function returnHistoryHtml(c){const rows=(S.returns||[]).filter(r=>r.clientId===c.id);if(!rows.length)return'';return '<div class="card"><div class="ct">Возвраты</div>'+rows.map(r=>'<p>'+esc(fmtD(dTs(r.date)))+': стоимость '+fmt(r.amount)+' ₽, возвращено деньгами '+fmt(r.refundAmount)+' ₽ · '+esc(r.reason)+'</p>').join('')+'</div>';}
